// === Tab: mySketch ===
let mandel;
let centerPosition;
let zoomRatio;

function preload() { 
	mandel = loadShader("https://openprocessing.org/sketch/2311023/files/shader.vert", "shader.frag");	
}

function setup() {

  let w = max(windowWidth, windowHeight);
  createCanvas(w, w, WEBGL);
  frameRate(30);
  centerPosition = [-0.5,0.0];
  zoomRatio = 1.0;
  shader(mandel);
  noStroke();

//  mandel.setUniform('p', [-0.5,0.0]);
//  mandel.setUniform('r', 1.5/zoomRatio );

}

function draw() {

  mandel.setUniform('p', centerPosition);
  mandel.setUniform('r', 1.5/zoomRatio );
  quad(-1, -1, 1, -1, 1, 1, -1, 1);

}

function mouseWheel(event) {
	centerPosition = [-0.5,0]
  if( event.delta > 0 ) {
    zoomRatio /= 1.1;
  } else {
    zoomRatio *= 1.1;
  }
  //if( zoomRatio < 1.0 ) zoomRatio = 1.0;

}

function mouseDragged() {

  let dx = ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))))/width;
  let dy = ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))/height;

  centerPosition[0] -= 2.0/zoomRatio*dx;
  centerPosition[1] += 2.0/zoomRatio*dy;

}

function keyPressed() {
  let d = 2.0/zoomRatio/40.0;
  if (keyCode === LEFT_ARROW) {
    centerPosition[0] += d;
  } else if (keyCode === RIGHT_ARROW) {
    centerPosition[0] -= d;
  } else if (keyCode === UP_ARROW) {
    centerPosition[1] -= d;
  } else if (keyCode === DOWN_ARROW) {
    centerPosition[1] += d;
  }
  if( key == '+' ) {
    zoomRatio *= 1.2;
  } else if( key == '-' ) {
    zoomRatio /= 1.2;
    if( zoomRatio < 1.0 ) zoomRatio = 1.0;
  }
}

